/* ============ ✏️ CONFIGURAÇÃO: o que você mais vai alterar está tudo aqui ============ */
const CONFIG = {
  brand: "Universo dos nós",                 // ✏️ nome da marca (lembre de trocar também <title> e as metatags no topo)
  whatsapp: "5567996981846",       // ✏️ NÚMERO REAL: código do país + DDD + número, só dígitos (ex.: 5567999998888)
  instagram: "etteartesanato",     // ✏️ usuário do Instagram, sem @ (este é o perfil atual)
  hours: "",                       // ✏️ horário de atendimento. Deixe vazio para não exibir
  legal: ""                        // ✏️ informações comerciais (CNPJ, cidade). Vazio = não exibe
};

/* ✏️ FOTOS: troque cada valor por um caminho de arquivo, ex.: "img/urso.jpg".
   Hoje estão embutidas só para a demonstração funcionar num único arquivo. */
const IMGS = {
  urso: "data:image/jpeg;base64,",
  artesa: "data:image/jpeg;base64,",
  porco: "data:image/jpeg;base64,",
  cesta1: "data:image/jpeg;base64,",
  cesta2: "data:image/jpeg;base64,"
};

/* ✏️ CATEGORIAS: aparecem como filtros acima do catálogo. */
const CATEGORIES = ["Amigurumis", "Cestas"];

/* ✏️ PRODUTOS: para adicionar uma peça, copie um bloco { ... } e preencha.
   price: número (ex.: 49.9) ou null para "Sob consulta". demo: true mostra a etiqueta "Exemplo".
   availability: texto livre (ex.: "Disponível", "Sob encomenda"). Não prometa o que não estiver confirmado. */
const PRODUCTS = [
  { id: "urso", name: "Amigo Urso", category: "Amigurumis", img: IMGS.urso,
    desc: "Urso de crochê com gravata-borboleta de bolinhas. 29 cm.",
    price: 49.9,   // ⚠️ valor do post do Instagram de jun/2022: confirme se continua o mesmo
    availability: "Consulte a disponibilidade", demo: false },
  { id: "porquinho", name: "Porquinho rosa", category: "Amigurumis", img: IMGS.porco,
    desc: "Porquinho de crochê com fita rosa no pescoço.",
    price: null, availability: "Consulte a disponibilidade", demo: true },
  { id: "cesta-frutas", name: "Cesta de frutas", category: "Cestas", img: IMGS.cesta1,
    desc: "Morangos, uvas e bananas de tecido e feltro, com saia de tecido e fita.",
    price: null, availability: "Consulte a disponibilidade", demo: true },
  { id: "cesta-legumes", name: "Cesta de legumes", category: "Cestas", img: IMGS.cesta2,
    desc: "Legumes de tecido e feltro, com barra de renda e alça de sisal.",
    price: null, availability: "Consulte a disponibilidade", demo: true }
];

/* ✏️ DEPOIMENTOS: só cole avaliações reais. Formato: { text: "…", author: "Nome" }. Vazio = mostra o convite. */
const TESTIMONIALS = [];

/* ============ Código do site (não precisa mexer daqui para baixo) ============ */
document.documentElement.classList.add("js");
const $ = (s, r = document) => r.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));
const money = n => n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const waLink = msg => `https://wa.me/${CONFIG.whatsapp}?text=${encodeURIComponent(msg)}`;

// Alternância manual entre os temas, com preferência salva neste navegador.
const themeToggle = $("#themeToggle");
function applyTheme(theme) {
  const isDark = theme === "dark";
  document.documentElement.dataset.theme = isDark ? "dark" : "light";
  themeToggle.textContent = isDark ? "☀" : "☾";
  themeToggle.setAttribute("aria-label", isDark ? "Ativar tema claro" : "Ativar tema escuro");
  themeToggle.setAttribute("aria-pressed", String(isDark));
  try { localStorage.setItem("lacada-theme", isDark ? "dark" : "light"); } catch (_) {}
}
themeToggle.addEventListener("click", () => {
  applyTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark");
});
applyTheme(document.documentElement.dataset.theme === "light" ? "light" : "dark");

document.querySelectorAll("[data-brand]").forEach(e => e.textContent = CONFIG.brand);
document.querySelectorAll("img[data-img]").forEach(i => i.src = IMGS[i.dataset.img]);
document.querySelectorAll("[data-wa]").forEach(a => { a.href = waLink(a.dataset.wa); a.target = "_blank"; a.rel = "noopener"; });
$("#ig").href = `https://instagram.com/${CONFIG.instagram}`; $("#ig").textContent = `Instagram @${CONFIG.instagram}`; $("#ig").target = "_blank";
if (CONFIG.hours) $("#hours").innerHTML = `<h3>Atendimento</h3><p>${esc(CONFIG.hours)}</p>`;
if (CONFIG.legal) $("#legal").textContent = CONFIG.legal;

let current = "Todos";
function card(p) {
  const msg = `Olá! Vi o “${p.name}” no site da ${CONFIG.brand} e gostaria de saber mais (valor e disponibilidade).`;
  return `<article class="card fade">${p.demo ? '<span class="tag">Exemplo</span>' : ""}
    <div class="ph-wrap"><img class="ph" src="${p.img}" alt="${esc(p.name)}" loading="lazy"></div>
    <h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p>
    <div class="meta"><span class="price">${p.price ? money(p.price) : "Sob consulta"}</span><span>${esc(p.availability)}</span></div>
    <a class="btn wa" href="${waLink(msg)}" target="_blank" rel="noopener" aria-label="Consultar ${esc(p.name)} pelo WhatsApp">Consultar no WhatsApp</a></article>`;
}
function render() {
  const list = PRODUCTS.filter(p => current === "Todos" || p.category === current);
  $("#grid").innerHTML = list.length ? list.map(card).join("")
    : `<div class="empty"><p style="margin:0 auto 14px">Ainda não há peças nesta categoria.</p><a class="btn wa" href="${waLink("Olá! Vim pelo site e gostaria de ver as peças disponíveis.")}" target="_blank" rel="noopener">Perguntar pelo WhatsApp</a></div>`;
  $("#grid").setAttribute("aria-busy", "false");
  $("#demoNotice").hidden = !PRODUCTS.some(p => p.demo);
  $("#filters").querySelectorAll("button").forEach(b => b.setAttribute("aria-pressed", b.dataset.c === current));
}
$("#filters").innerHTML = ["Todos", ...CATEGORIES].map(c => `<button type="button" data-c="${c}">${c}</button>`).join("");
$("#filters").addEventListener("click", e => { const b = e.target.closest("button"); if (b) { current = b.dataset.c; render(); } });
render();

$("#quotes").innerHTML = TESTIMONIALS.length
  ? TESTIMONIALS.map(t => `<blockquote><p>“${esc(t.text)}”</p><footer>${esc(t.author)}</footer></blockquote>`).join("")
  : `<blockquote><p>Recebeu uma peça nossa? Conte como foi.</p><a class="btn alt" href="${waLink("Olá! Recebi uma peça e gostaria de deixar meu depoimento.")}" target="_blank" rel="noopener">Enviar depoimento</a></blockquote>`;